"""Local stand-in for ``backports.zstd`` / stdlib ``compression.zstd``.

py7zr imports ZSTD at module level::

    if sys.version_info >= (3, 14):
        from compression import zstd
    else:
        from backports import zstd

This project bundles a py7zr build for CPython 3.14 but only runs on
CPython 3.13, and has no network access to install the real backport.
This stand-in exposes the exact API surface py7zr touches
(``zstd_version_info``, ``ZstdCompressor``, ``ZstdDecompressor``) and
raises a clear ImportError if ZSTD-compressed data is actually
(de)compressed, which does not happen for non-ZSTD 7z archives.
"""

# Claim a real, recent zstd version so py7zr's compatibility checks
# (comparing the archive header's zstd major/minor against this value)
# behave sensibly. The codec classes below are not functional.
zstd_version_info = (1, 5, 6)


class _ZstdUnavailable:
    def __new__(cls, *args, **kwargs):
        raise ImportError(
            "zstd: no usable ZSTD implementation in this environment; the local "
            "py7zr build was compiled for CPython 3.14 and backports.zstd is not "
            "installed. ZSTD-compressed 7z files cannot be (de)compressed here."
        )


class ZstdCompressor(_ZstdUnavailable):
    """Placeholder for zstd.ZstdCompressor (unavailable here)."""


class ZstdDecompressor(_ZstdUnavailable):
    """Placeholder for zstd.ZstdDecompressor (unavailable here)."""
